begin;
update public.site_faqs set answer='Report는 부산 관광 자원 15곳을 소개합니다. 이 중 [1]–[6]의 주소·상세 소개와 팝업 사진을 한국관광공사 국문 관광정보 서비스_GW·웰니스관광정보 API로 갱신합니다. [7]–[15]는 공식 안내를 기준으로 편집한 정보이며 카드의 픽셀 이미지는 고정입니다. 연결 상태와 최근 확인 시각을 표시하고, API 응답은 최대 30분 캐시합니다. 전시·예약·운영 일정은 공식 홈페이지에서 확인할 수 있습니다.', keywords=array['공공데이터','api','데이터 연결','실시간','자동 갱신','업데이트','led'], embedding=null, updated_at=now() where slug='report-api';
update public.site_faqs set answer='Report의 관광 자원 15곳은 녹색 계열의 정사각형 픽셀 아트 카드로 소개합니다. 카드는 두 줄로 배치된 가로 목록이며, 픽셀 이미지를 누르면 Windows 95 탐색기 스타일의 상세 팝업에서 소개·체험 프로그램·방문자 후기를 볼 수 있습니다. 부산현대미술관에는 모션 카드뉴스도 있습니다. API가 갱신돼도 카드 이미지는 유지됩니다.', keywords=array['픽셀','픽셀 이미지','8비트','8bit','카드 이미지','녹색 이미지'], embedding=null, updated_at=now() where slug='report-pixel';
update public.site_faqs set answer='Report의 부산 관광 자원은 15곳입니다. [1] 부산현대미술관, [2] 부산시립미술관, [3] 뮤지엄 원, [4] 아르떼뮤지엄 부산, [5] 허심청, [6] 부산어린이대공원 치유의 숲, [7] 부산근현대역사관, [8] 깡깡이예술마을, [9] 도모헌, [10] F1963, [11] 고은사진미술관, [12] 영화의전당, [13] 흰여울문화마을, [14] 부산박물관, [15] 복천박물관. 두 줄 가로 목록을 좌우로 넘겨 보고, 각 픽셀 이미지를 누르면 상세 소개와 공식 홈페이지를 확인할 수 있습니다.', keywords=array['선정 관광 자원','관광 자원','관광지 목록','리포트 관광지','15곳','열다섯 곳'], embedding=null, updated_at=now() where slug='tour-resources';
update public.site_faqs set answer='Contents 프로젝트 5개, Report 관광 자원 15곳, SNS 채널과 영상·카드뉴스는 가로 목록으로 살펴볼 수 있습니다. Report의 관광지는 두 줄로 배치됩니다. PC는 좌우 화살표·가로 스크롤, 모바일은 스와이프를 사용합니다. 목록에 키보드 초점을 두고 좌우 방향키와 Home·End도 사용할 수 있습니다. 관광지 이미지는 상세 팝업을 열고, 영상 크게 보기는 원본 비율로 감상할 수 있습니다.', keywords=array['슬라이드','좌우로','넘겨 보기','넘기는','스와이프','크게 보기','크게 보','영상 재생','영상 비율','영상 소리','프로젝트 넘기','관광지 넘기','채널 넘기','카드 넘기'], embedding=null, updated_at=now() where slug='media-navigation';
update public.site_faqs set answer='final_project는 외국인 부산 여행자를 위한 음식 탐색 웹앱 무보소(I EAT BUSAN)를 소개합니다. 음식 검색·먹는 방법·알레르기 안내, 지도·식당 탐색, 커뮤니티와 음식 도우미를 실제 화면으로 볼 수 있습니다. 김준철은 팀장·UX/UI 디자이너, 문소정은 PM, 박현민은 개발 총괄, 이정규는 DB 개발·영상 제작, 김채운은 마케팅·영상 제작을 담당했습니다. 페이지의 웹앱 직접 보기 링크로 서비스를 이용할 수 있습니다.', keywords=array['final','final_project','최종 프로젝트','완성 프로젝트','무보소','muboso','i eat busan'], embedding=null, updated_at=now() where slug='final-project';
commit;
